package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

type SearchRequest struct {
	Category string `json:"category"`
	MinPrice string `json:"min_price"`
	MaxPrice string `json:"max_price"`
	SortBy   string `json:"sort_by"`
	Keyword  string `json:"keyword"`
}

type Product struct {
	ID    int     `json:"id"`
	Name  string  `json:"name"`
	Price float64 `json:"price"`
}

func init() {
	connStr := os.Getenv("DATABASE_URL")
	var err error
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

// sanitizeSortColumn attempts to validate sort column but is bypassable
func sanitizeSortColumn(col string) string {
	allowed := []string{"name", "price", "id", "created_at"}
	for _, a := range allowed {
		if strings.EqualFold(col, a) {
			return a
		}
	}
	// Falls back to raw input if not in allowlist - developer assumed
	// the frontend dropdown only sends valid values
	return col
}

func searchProducts(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Invalid JSON", 400)
		return
	}

	// Build query with parameterized values for most fields
	baseQuery := "SELECT id, name, price FROM products WHERE 1=1"
	args := []interface{}{}
	argIdx := 1

	if req.Category != "" {
		baseQuery += fmt.Sprintf(" AND category = $%d", argIdx)
		args = append(args, req.Category)
		argIdx++
	}

	if req.MinPrice != "" {
		baseQuery += fmt.Sprintf(" AND price >= $%d", argIdx)
		args = append(args, req.MinPrice)
		argIdx++
	}

	if req.MaxPrice != "" {
		baseQuery += fmt.Sprintf(" AND price <= $%d", argIdx)
		args = append(args, req.MaxPrice)
		argIdx++
	}

	if req.Keyword != "" {
		baseQuery += fmt.Sprintf(" AND name ILIKE $%d", argIdx)
		args = append(args, "%"+req.Keyword+"%")
		argIdx++
	}

	// ORDER BY clause - uses sanitizeSortColumn which has a bypass
	sortCol := sanitizeSortColumn(req.SortBy)
	if sortCol != "" {
		baseQuery += " ORDER BY " + sortCol
	}

	baseQuery += " LIMIT 50"

	rows, err := db.Query(baseQuery, args...)
	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal error", 500)
		return
	}
	defer rows.Close()

	var products []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Price); err != nil {
			continue
		}
		products = append(products, p)
	}

	w.Header().Set("Content-Type", "application/json")
	json.NewEncoder(w).Encode(products)
}

func healthCheck(w http.ResponseWriter, r *http.Request) {
	w.Write([]byte("ok"))
}

func main() {
	http.HandleFunc("/api/products/search", searchProducts)
	http.HandleFunc("/health", healthCheck)
	log.Printf("Starting server on :8080")
	log.Fatal(http.ListenAndServe(":8080", nil))
}
